import time
def insertionSort(myarray):
    sortedarray = []
    for currentValue in myarray:
        index = 0
        for j in range(len(sortedarray)):
            if sortedarray[j] < currentValue:
                index = j + 1
            else:
                break
        sortedarray.insert(index, currentValue)
    return sortedarray

